                s=subs[idx]
                fr = 1 if (idx//2)==(k//2) else -1
                fc = 1 if (idx%2)==(k%2) else -1
                for r in range(h):
                    for c in range(w):
                        if s[r][c]:
                            rr,cc=(r if fr==1 else h-1-r),(c if fc==1 else w-1-c)
